    fn render_audio_clips_dialog(&mut self) {
        let Some(project_path) = self.current_path.as_deref() else {
            self.status = "Open a project before rendering audio clips".to_owned();
            return;
        };
        if self.document.is_none() {
            self.status = "Open a project before rendering audio clips".to_owned();
            return;
        }
        if self.pending_audio_clip_export.is_some() {
            self.status = "An audio clip render is already running".to_owned();
            return;
        }
        let project_stem = project_path
            .file_stem()
            .map(|stem| stem.to_string_lossy().into_owned())
            .unwrap_or_else(|| "FL_Studio_Project".to_owned());
        let output_format = self.playlist_song_output_format;
        let Some(output_path) = add_audio_render_file_filter(
            rfd::FileDialog::new()
                .set_title("Render Playlist audio clips")
                .set_file_name(format!(
                    "{project_stem}_audio.{}",
                    output_format.extension()
                )),
            output_format,
        )
        .save_file() else {
            return;
        };
        let options = AudioClipRenderOptions {
            arrangement_id: self.selected_arrangement.unwrap_or_default(),
            sample_rate: self.audio_settings.sample_rate,
            wav_sample_format: self.playlist_render_format,
            wav_dither_mode: if self.playlist_render_dither {
                WavDitherMode::Tpdf
            } else {
                WavDitherMode::Off
            },
            wav_channel_mode: self.playlist_render_channel_mode,
            resampling_quality: self.playlist_render_quality,
            soloed_playlist_track_range: self.soloed_playlist_track_range,
            ..AudioClipRenderOptions::default()
        };
        let output = self.audio_render_output();
        self.start_audio_clip_export(options, output_path, output);
    }

    fn render_selected_audio_clip_dialog(&mut self, start_from_song_start: bool) {
        let Some((arrangement_id, clip_index)) = self.selected_playlist_audio_clip() else {
            self.status = "Select an enabled audio-channel clip in the Playlist first".to_owned();
            return;
        };
        if self.pending_audio_clip_export.is_some() {
            self.status = "An audio clip render is already running".to_owned();
            return;
        }
        let Some(project_path) = self.current_path.as_deref() else {
            self.status = "Open a project before rendering its selected audio clip".to_owned();
            return;
        };
        let project_stem = project_path
            .file_stem()
            .map(|stem| stem.to_string_lossy().into_owned())
            .unwrap_or_else(|| "FL_Studio_Project".to_owned());
        let output_format = self.playlist_song_output_format;
        let Some(output_path) = add_audio_render_file_filter(
            rfd::FileDialog::new()
                .set_title(if start_from_song_start {
                    "Render selected Playlist audio clip from song start"
                } else {
                    "Render selected Playlist audio clip from clip start"
                })
                .set_file_name(format!(
                    "{project_stem}_clip_{}_{}.{}",
                    clip_index + 1,
                    if start_from_song_start {
                        "song_start"
                    } else {
                        "clip_start"
                    },
                    output_format.extension()
                )),
            output_format,
        )
        .save_file() else {
            return;
        };
        let options = AudioClipRenderOptions {
            arrangement_id,
            sample_rate: self.audio_settings.sample_rate,
            wav_sample_format: self.playlist_render_format,
            wav_dither_mode: if self.playlist_render_dither {
                WavDitherMode::Tpdf
            } else {
                WavDitherMode::Off
            },
            wav_channel_mode: self.playlist_render_channel_mode,
            resampling_quality: self.playlist_render_quality,
            clip_index: Some(clip_index),
            start_from_song_start,
            soloed_playlist_track_range: self.soloed_playlist_track_range,
        };
        let output = self.audio_render_output();
        self.start_audio_clip_export(options, output_path, output);
    }

    fn audio_render_output(&self) -> AudioRenderOutput {
        match self.playlist_song_output_format {
            PlaylistSongOutputFormat::Wav => AudioRenderOutput::Wav,
            PlaylistSongOutputFormat::Flac => AudioRenderOutput::Flac {
                bits_per_sample: self.playlist_render_flac_bits_per_sample,
            },
            PlaylistSongOutputFormat::Ogg => AudioRenderOutput::Ogg {
                bitrate_kbps: self.playlist_render_ogg_bitrate_kbps,
            },
            PlaylistSongOutputFormat::Mp3 => AudioRenderOutput::Mp3 {
                bitrate_kbps: self.playlist_render_mp3_bitrate_kbps,
            },
        }
    }

    fn start_audio_clip_export(
        &mut self,
        options: AudioClipRenderOptions,
        output_path: PathBuf,
        output_format: AudioRenderOutput,
    ) {
        let Some(project_path) = self.sample_project_path() else {
            self.status = "Save the project before rendering its audio clips".to_owned();
            return;
        };
        let Some(document) = self.document.as_ref() else {
            self.status = "Open a project before rendering its audio clips".to_owned();
            return;
        };
        if self.pending_audio_clip_export.is_some() {
            self.status = "An audio clip render is already running".to_owned();
            return;
        }
        let document = document.clone();
        let package_workspace = self.package_workspace.clone();
        let output_path_for_worker = output_path.clone();
        let (sender, receiver) = mpsc::sync_channel(1);
        let worker = thread::Builder::new()
            .name("playlist-audio-clip-render".to_owned())
            .spawn(move || {
                let _package_workspace = package_workspace;
                let result = render_audio_clips_to_file(
                    &document,
                    &project_path,
                    options,
                    &output_path_for_worker,
                    output_format,
                );
                let _ = sender.send(result);
            });
        match worker {
            Ok(worker) => {
                let selected_clip_index = options.clip_index;
                self.pending_audio_clip_export = Some(PendingAudioClipExport {
                    receiver,
                    worker,
                    output_path: output_path.clone(),
                    selected_clip_index,
                    start_from_song_start: options.start_from_song_start,
                });
                self.status = match selected_clip_index {
                    Some(clip_index) => format!(
                        "Rendering selected Playlist audio clip {} from {} to {}…",
                        clip_index + 1,
                        if options.start_from_song_start {
                            "song start"
                        } else {
                            "clip start"
                        },
                        output_path.display()
                    ),
                    None => format!(
                        "Rendering Playlist audio clips to {}…",
                        output_path.display()
                    ),
                };
            }
            Err(error) => {
                self.status = format!("Could not start Playlist audio clip render: {error}");
            }
        }
    }

    fn poll_audio_clip_export(&mut self) {
        let completed = self.pending_audio_clip_export.as_ref().and_then(|pending| {
            match pending.receiver.try_recv() {
                Ok(result) => Some(result),
                Err(TryRecvError::Disconnected) => Some(Err(
                    "Playlist audio clip render worker stopped unexpectedly".to_owned(),
                )),
                Err(TryRecvError::Empty) => None,
            }
        });
        let Some(result) = completed else {
            return;
        };
        let Some(pending) = self.pending_audio_clip_export.take() else {
            return;
        };
        if pending.worker.join().is_err() {
            self.status = "Playlist audio clip render worker panicked".to_owned();
            return;
        }
        match result {
            Ok(summary) => {
                self.status = match pending.selected_clip_index {
                    Some(clip_index) => format!(
                        "Rendered selected Playlist audio clip {} from {} to {} at {} Hz",
                        clip_index + 1,
                        if pending.start_from_song_start {
                            "song start"
                        } else {
                            "clip start"
                        },
                        pending.output_path.display(),
                        summary.sample_rate,
                    ),
                    None => format!(
                        "Rendered {} Playlist audio clips to {} at {} Hz ({} skipped for non-default scale)",
                        summary.clips_rendered,
                        pending.output_path.display(),
                        summary.sample_rate,
                        summary.clips_skipped_unsupported_scale,
                    ),
                };
            }
            Err(error) => {
                self.status = format!("Could not render Playlist audio clips: {error}");
            }
        }
    }

    fn render_playlist_dialog(&mut self) {
        let (Some(project_path), Some(document)) =
            (self.current_path.as_deref(), self.document.as_ref())
        else {
            self.status = "Open a project before rendering the Playlist".to_owned();
            return;
        };
        if self.pending_song_render.is_some() {
            self.status = "A Playlist render is already running".to_owned();
            return;
        }
        if self.playing
            || self.project_playback_loaded
            || self.pending_audio_render.is_some()
            || self.pending_vst3_stream.is_some()
            || self.pending_sampler_stream.is_some()
        {
            self.status =
                "Stop Song playback or pattern preview before rendering the Playlist".to_owned();
            return;
        }
        let project_stem = project_path
            .file_stem()
            .map(|stem| stem.to_string_lossy().into_owned())
            .unwrap_or_else(|| "FL_Studio_Project".to_owned());
        let output_format = self.playlist_song_output_format;
        let file_dialog = rfd::FileDialog::new()
            .set_title("Render Playlist mix")
            .set_file_name(format!("{project_stem}.{}", output_format.extension()));
        let file_dialog = match output_format {
            PlaylistSongOutputFormat::Wav => file_dialog.add_filter("WAV audio", &["wav"]),
            PlaylistSongOutputFormat::Flac => file_dialog.add_filter("FLAC audio", &["flac"]),
            PlaylistSongOutputFormat::Ogg => file_dialog.add_filter("Ogg Vorbis audio", &["ogg"]),
            PlaylistSongOutputFormat::Mp3 => file_dialog.add_filter("MP3 audio", &["mp3"]),
        };
        let Some(output_path) = file_dialog.save_file() else {
            return;
        };
        let flac_bits_per_sample = self.playlist_render_flac_bits_per_sample;
        let ogg_bitrate_kbps = self.playlist_render_ogg_bitrate_kbps;
        let mp3_bitrate_kbps = self.playlist_render_mp3_bitrate_kbps;

        let options = PlaylistRenderOptions {
            arrangement_id: self.selected_arrangement.unwrap_or_default(),
            sample_rate: self.audio_settings.sample_rate,
            soloed_playlist_track_range: self.soloed_playlist_track_range,
            read_sample_root_note: self.read_sample_root_note,
            wav_sample_format: self.playlist_render_format,
            wav_dither_mode: if self.playlist_render_dither {
                WavDitherMode::Tpdf
            } else {
                WavDitherMode::Off
            },
            resampling_quality: self.playlist_render_quality,
            wav_channel_mode: self.playlist_render_channel_mode,
            tail_seconds: self.playlist_render_tail_seconds,
            ..PlaylistRenderOptions::default()
        };
        let vst3_processor = self
            .vst3_host
            .as_ref()
            .map(|host| {
                host.prepare_playlist_stream(
                    document,
                    options,
                    &self.channel_vst3_instances,
                    self.playlist_render_include_plugin_tails,
                )
            })
            .transpose();
        let vst3_processor = match vst3_processor {
            Ok(processor) => processor,
            Err(error) => {
                self.status = format!("Could not prepare Playlist VST3 instruments: {error}");
                return;
            }
        };

        let project_path = self
            .sample_project_path()
            .unwrap_or_else(|| project_path.to_path_buf());
        let document = document.clone();
        let output_path_for_worker = output_path.clone();
        let cancelled = Arc::new(AtomicBool::new(false));
        let worker_cancelled = Arc::clone(&cancelled);
        let (sender, receiver) = mpsc::sync_channel(1);
        let worker = thread::Builder::new()
            .name("playlist-render".to_owned())
            .spawn(move || {
                let result = match output_format {
                    PlaylistSongOutputFormat::Wav => render_playlist_with_vst3_to_wav_cancellable(
                        &document,
                        &project_path,
                        options,
                        &output_path_for_worker,
                        vst3_processor,
                        &worker_cancelled,
                    ),
                    PlaylistSongOutputFormat::Flac => {
                        render_playlist_with_vst3_to_flac_cancellable(
                            &document,
                            &project_path,
                            options,
                            &output_path_for_worker,
                            flac_bits_per_sample,
                            vst3_processor,
                            &worker_cancelled,
                        )
                    }
                    PlaylistSongOutputFormat::Ogg => render_playlist_with_vst3_to_ogg_cancellable(
                        &document,
                        &project_path,
                        options,
                        &output_path_for_worker,
                        ogg_bitrate_kbps,
                        vst3_processor,
                        &worker_cancelled,
                    ),
                    PlaylistSongOutputFormat::Mp3 => render_playlist_with_vst3_to_mp3_cancellable(
                        &document,
                        &project_path,
                        options,
                        &output_path_for_worker,
                        mp3_bitrate_kbps,
                        vst3_processor,
                        &worker_cancelled,
                    ),
                };
                let _ = sender.send(result);
            });
        match worker {
            Ok(worker) => {
                self.pending_song_render = Some(PendingSongRender {
                    receiver,
                    cancelled,
                    worker,
                    output_path: output_path.clone(),
                });
                self.status = format!("Rendering Playlist mix to {}…", output_path.display());
            }
            Err(error) => {
                self.status = format!("Could not start Playlist render worker: {error}");
            }
        }
    }

    fn poll_song_render(&mut self) {
        let completed = self.pending_song_render.as_ref().and_then(|pending| {
            match pending.receiver.try_recv() {
                Ok(result) => Some(result),
                Err(TryRecvError::Disconnected) => {
                    Some(Err("Playlist render worker stopped unexpectedly".to_owned()))
                }
                Err(TryRecvError::Empty) => None,
            }
        });
        let Some(result) = completed else {
            return;
        };
        let Some(pending) = self.pending_song_render.take() else {
            return;
        };
        if pending.worker.join().is_err() {
            self.status = "Playlist render worker panicked".to_owned();
            return;
        }
        match result {
            Ok(summary) => {
                self.status = format!(
                    "Rendered {} audio clips, {} Sampler clips ({} notes), and {} VST3 channels ({} notes) to {} at {} Hz; {} plug-in channels unloaded, {} scaled audio and {} scaled pattern clips skipped. Mixer effects and automation were not rendered",
                    summary.audio_clips_rendered,
                    summary.sampler_pattern_clips_rendered,
                    summary.sampler_notes_rendered,
                    summary.vst3_plugin_channels_rendered,
                    summary.vst3_notes_rendered,
                    pending.output_path.display(),
                    summary.sample_rate,
                    summary.vst3_plugin_channels_unloaded,
                    summary.audio_clips_skipped_unsupported_scale,
                    summary.pattern_clips_skipped_unsupported_scale,
                );
            }
            Err(error) => self.status = format!("Could not render Playlist mix: {error}"),
        }
    }

