fn load_browser_tags() -> BTreeMap<PathBuf, BTreeSet<String>> {
    let Some(path) = browser_tags_file() else {
        return BTreeMap::new();
    };
    let Ok(contents) = fs::read_to_string(path) else {
        return BTreeMap::new();
    };
    let mut tags_by_path = BTreeMap::new();
    for line in contents.lines() {
        let mut fields = line.split('\t');
        let Some(path) = fields.next().filter(|path| !path.is_empty()) else {
            continue;
        };
        let tags = fields
            .flat_map(|field| field.split(','))
            .map(str::trim)
            .filter(|tag| !tag.is_empty())
            .map(str::to_owned)
            .collect::<BTreeSet<_>>();
        if !tags.is_empty() {
            tags_by_path.insert(PathBuf::from(path), tags);
        }
    }
    tags_by_path
}

fn save_browser_tags(tags_by_path: &BTreeMap<PathBuf, BTreeSet<String>>) -> Result<(), String> {
    let path = browser_tags_file()
        .ok_or_else(|| "the user configuration folder is not available".to_owned())?;
    let parent = path
        .parent()
        .ok_or_else(|| "the Browser tags path has no parent folder".to_owned())?;
    fs::create_dir_all(parent)
        .map_err(|error| format!("could not create {}: {error}", parent.display()))?;
    let contents = tags_by_path
        .iter()
        .filter(|(_, tags)| !tags.is_empty())
        .map(|(path, tags)| {
            let mut line = path.to_string_lossy().into_owned();
            for tag in tags {
                line.push('\t');
                line.push_str(&tag.replace(['\t', '\n', '\r'], " "));
            }
            line
        })
        .collect::<Vec<_>>()
        .join("\n");
    fs::write(&path, contents)
        .map_err(|error| format!("could not write {}: {error}", path.display()))
}

fn browser_search_filter_key(filter: BrowserFilter) -> &'static str {
    match filter {
        BrowserFilter::All => "all",
        BrowserFilter::Audio => "audio",
        BrowserFilter::Projects => "projects",
        BrowserFilter::Presets => "presets",
    }
}

fn parse_browser_search_filter(value: &str) -> Option<BrowserFilter> {
    match value {
        "all" => Some(BrowserFilter::All),
        "audio" => Some(BrowserFilter::Audio),
        "projects" => Some(BrowserFilter::Projects),
        "presets" => Some(BrowserFilter::Presets),
        _ => None,
    }
}

fn browser_tag_logic_key(logic: BrowserTagLogic) -> &'static str {
    match logic {
        BrowserTagLogic::Any => "any",
        BrowserTagLogic::All => "all",
    }
}

fn parse_browser_tag_logic(value: &str) -> Option<BrowserTagLogic> {
    match value {
        "any" => Some(BrowserTagLogic::Any),
        "all" => Some(BrowserTagLogic::All),
        _ => None,
    }
}

fn encode_browser_search_field(value: &str) -> String {
    let mut encoded = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '%' => encoded.push_str("%25"),
            '\t' => encoded.push_str("%09"),
            '\n' => encoded.push_str("%0A"),
            '\r' => encoded.push_str("%0D"),
            _ => encoded.push(character),
        }
    }
    encoded
}

fn decode_browser_search_field(value: &str) -> String {
    let bytes = value.as_bytes();
    let mut decoded = Vec::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        if bytes[index] == b'%' && index + 2 < bytes.len() {
            let high = (bytes[index + 1] as char).to_digit(16);
            let low = (bytes[index + 2] as char).to_digit(16);
            if let (Some(high), Some(low)) = (high, low) {
                decoded.push(((high << 4) | low) as u8);
                index += 3;
                continue;
            }
        }
        decoded.push(bytes[index]);
        index += 1;
    }
    String::from_utf8_lossy(&decoded).into_owned()
}

fn load_browser_saved_searches() -> Vec<SavedBrowserSearch> {
    let Some(path) = browser_saved_searches_file() else {
        return Vec::new();
    };
    let Ok(contents) = fs::read_to_string(path) else {
        return Vec::new();
    };
    let mut searches = Vec::new();
    for line in contents.lines() {
        let mut fields = line.split('\t');
        let version = fields.next();
        let (Some(name), Some(query), Some(filter), Some(all_roots), Some(recursive), Some(path)) = (
            fields.next(),
            fields.next(),
            fields.next(),
            fields.next(),
            fields.next(),
            fields.next(),
        ) else {
            continue;
        };
        let (tag_logic, hidden, color, icon, selected_tags) = match version {
            Some("v1") if fields.next().is_none() => (
                BrowserTagLogic::Any,
                false,
                BrowserTabColor::default(),
                BrowserTabIcon::default(),
                BTreeSet::new(),
            ),
            Some("v2") => {
                let Some(tag_logic) = fields.next().and_then(parse_browser_tag_logic) else {
                    continue;
                };
                let selected_tags = fields
                    .map(decode_browser_search_field)
                    .map(|tag| tag.trim().to_owned())
                    .filter(|tag| !tag.is_empty())
                    .collect::<BTreeSet<_>>();
                (
                    tag_logic,
                    false,
                    BrowserTabColor::default(),
                    BrowserTabIcon::default(),
                    selected_tags,
                )
            }
            Some(version @ ("v3" | "v4")) => {
                let Some(tag_logic) = fields.next().and_then(parse_browser_tag_logic) else {
                    continue;
                };
                let Some(Ok(hidden)) = fields.next().map(str::parse::<bool>) else {
                    continue;
                };
                let (color, icon) = if version == "v4" {
                    let Some(color) = fields.next().and_then(BrowserTabColor::parse) else {
                        continue;
                    };
                    let Some(icon) = fields.next().and_then(BrowserTabIcon::parse) else {
                        continue;
                    };
                    (color, icon)
                } else {
                    (BrowserTabColor::default(), BrowserTabIcon::default())
                };
                let selected_tags = fields
                    .map(decode_browser_search_field)
                    .map(|tag| tag.trim().to_owned())
                    .filter(|tag| !tag.is_empty())
                    .collect::<BTreeSet<_>>();
                (tag_logic, hidden, color, icon, selected_tags)
            }
            _ => continue,
        };
        let name = decode_browser_search_field(name);
        let query = decode_browser_search_field(query);
        let Some(filter) = parse_browser_search_filter(filter) else {
            continue;
        };
        let (Ok(all_roots), Ok(recursive)) = (all_roots.parse::<bool>(), recursive.parse::<bool>())
        else {
            continue;
        };
        let path = decode_browser_search_field(path);
        if name.trim().is_empty() || (!all_roots && path.is_empty()) {
            continue;
        }
        let search = SavedBrowserSearch {
            name: name.trim().to_owned(),
            query,
            filter,
            all_roots,
            recursive,
            path: if all_roots {
                PathBuf::new()
            } else {
                PathBuf::from(path)
            },
            tag_logic,
            selected_tags,
            hidden,
            color,
            icon,
        };
        if let Some(existing) = searches
            .iter_mut()
            .find(|existing: &&mut SavedBrowserSearch| {
                existing.name.eq_ignore_ascii_case(&search.name)
            })
        {
            *existing = search;
        } else {
            searches.push(search);
        }
    }
    searches
}

fn save_browser_saved_searches(searches: &[SavedBrowserSearch]) -> Result<(), String> {
    let path = browser_saved_searches_file()
        .ok_or_else(|| "the user configuration folder is not available".to_owned())?;
    let parent = path
        .parent()
        .ok_or_else(|| "the Browser saved searches path has no parent folder".to_owned())?;
    fs::create_dir_all(parent)
        .map_err(|error| format!("could not create {}: {error}", parent.display()))?;
    let contents = searches
        .iter()
        .map(|search| {
            let path = if search.all_roots {
                String::new()
            } else {
                search.path.to_string_lossy().into_owned()
            };
            let mut fields = vec![
                "v4".to_owned(),
                encode_browser_search_field(&search.name),
                encode_browser_search_field(&search.query),
                browser_search_filter_key(search.filter).to_owned(),
                search.all_roots.to_string(),
                search.recursive.to_string(),
                encode_browser_search_field(&path),
                browser_tag_logic_key(search.tag_logic).to_owned(),
                search.hidden.to_string(),
                search.color.key().to_owned(),
                search.icon.key().to_owned(),
            ];
            fields.extend(
                search
                    .selected_tags
                    .iter()
                    .map(|tag| encode_browser_search_field(tag)),
            );
            fields.join("\t")
        })
        .collect::<Vec<_>>()
        .join("\n");
    fs::write(&path, contents)
        .map_err(|error| format!("could not write {}: {error}", path.display()))
}

fn browser_factory_packs_directory() -> Option<PathBuf> {
    let resolver = SamplePathResolver::new(Path::new("browser-root.flp"));
    for root in resolver.factory_roots() {
        for candidate in [
            root.join("Data").join("Patches").join("Packs"),
            root.join("Patches").join("Packs"),
            root.join("Packs"),
        ] {
            if candidate.is_dir() {
                return Some(candidate);
            }
        }
        if root
            .file_name()
            .is_some_and(|name| name.to_string_lossy().eq_ignore_ascii_case("Packs"))
            && root.is_dir()
        {
            return Some(root.clone());
        }
    }
    None
}

fn browser_file_kind(path: &Path) -> Option<BrowserFileKind> {
    let extension = path
        .extension()
        .and_then(|extension| extension.to_str())?
        .to_ascii_lowercase();
    match extension.as_str() {
        "wav" | "wave" | "mp3" | "m4a" | "ogg" | "flac" | "aif" | "aiff" | "wv" => {
            Some(BrowserFileKind::Audio)
        }
        "flp" | "zip" => Some(BrowserFileKind::Project),
        "fst" | "fxp" | "fxb" | "vstpreset" => Some(BrowserFileKind::Preset),
        "mid" | "midi" => Some(BrowserFileKind::Midi),
        _ => None,
    }
}

fn browser_filter_matches(path: &Path, filter: BrowserFilter) -> bool {
    matches!(
        (filter, browser_file_kind(path)),
        (BrowserFilter::All, Some(_))
            | (BrowserFilter::Audio, Some(BrowserFileKind::Audio))
            | (BrowserFilter::Projects, Some(BrowserFileKind::Project))
            | (BrowserFilter::Presets, Some(BrowserFileKind::Preset))
    )
}

fn browser_tag_selection_matches(
    logic: BrowserTagLogic,
    selected_tags: &BTreeSet<String>,
    file_tags: Option<&BTreeSet<String>>,
) -> bool {
    if selected_tags.is_empty() {
        return true;
    }
    let Some(file_tags) = file_tags else {
        return false;
    };
    match logic {
        BrowserTagLogic::Any => selected_tags.iter().any(|selected| {
            let selected = selected.to_lowercase();
            file_tags.iter().any(|tag| tag.to_lowercase() == selected)
        }),
        BrowserTagLogic::All => selected_tags.iter().all(|selected| {
            let selected = selected.to_lowercase();
            file_tags.iter().any(|tag| tag.to_lowercase() == selected)
        }),
    }
}

fn browser_file_icon(path: &Path) -> &'static str {
    match browser_file_kind(path) {
        Some(BrowserFileKind::Audio) => "♫",
        Some(BrowserFileKind::Project) => "FLP",
        Some(BrowserFileKind::Preset) => "FST",
        Some(BrowserFileKind::Midi) => "MIDI",
        None => "·",
    }
}

fn clip_name(clip: &PlaylistClip, tracks: &[PlaylistTrack]) -> String {
    match clip.target() {
        flp_rebuild::PlaylistClipTarget::Pattern { id } => format!("Pattern {}", id),
        flp_rebuild::PlaylistClipTarget::Channel { id } => tracks
            .iter()
            .find(|track| Some(track.id) == clip.playlist_track_id())
            .and_then(|track| track.name.as_deref())
            .map(str::to_owned)
            .unwrap_or_else(|| format!("Channel {}", id)),
    }
}

fn note_name(key: u16) -> String {
    const NAMES: [&str; 12] = [
        "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B",
    ];
    format!("{}{}", NAMES[(key % 12) as usize], key / 12)
}

fn draw_audio_clip_waveform(
    painter: &egui::Painter,
    clip_rect: egui::Rect,
    clip: &PlaylistClip,
    waveform: &AudioWaveform,
    mode: PlaylistWaveformMode,
) {
    if waveform.peaks.is_empty() || waveform.frame_count == 0 || waveform.sample_rate == 0 {
        return;
    }
    let full_frame_count = waveform.frame_count;
    let to_frame = |milliseconds: f32| -> Option<u64> {
        let frame = f64::from(milliseconds) * f64::from(waveform.sample_rate) / 1000.0;
        (frame.is_finite() && frame >= 0.0 && frame <= u64::MAX as f64)
            .then_some(frame.round() as u64)
    };
    let source_window = if clip.start_offset == -1.0 && clip.end_offset == -1.0 {
        Some((0, full_frame_count))
    } else {
        to_frame(clip.start_offset)
            .zip(to_frame(clip.end_offset))
            .map(|(start, end)| (start.min(full_frame_count), end.min(full_frame_count)))
            .filter(|(start, end)| start < end)
    };
    let Some((source_start, source_end)) = source_window else {
        return;
    };
    if mode == PlaylistWaveformMode::Spectral {
        draw_spectral_audio_clip(painter, clip_rect, waveform, source_start, source_end);
        return;
    }
    let columns = clip_rect.width().ceil().clamp(1.0, 1024.0) as usize;
    let frame_count = u128::from(full_frame_count);
    let stereo = mode == PlaylistWaveformMode::Stereo && waveform.channel_peaks.len() >= 2;
    let display_channels = if stereo { 2 } else { 1 };
    if stereo {
        let center_y = clip_rect.center().y;
        painter.line_segment(
            [
                egui::pos2(clip_rect.left(), center_y),
                egui::pos2(clip_rect.right(), center_y),
            ],
            Stroke::new(0.5, Color32::from_rgba_unmultiplied(20, 20, 20, 115)),
        );
    }
    for display_channel in 0..display_channels {
        let peaks = if stereo {
            &waveform.channel_peaks[display_channel]
        } else {
            &waveform.peaks
        };
        if peaks.is_empty() {
            continue;
        }
        let peak_count = peaks.len() as u128;
        let lane = if stereo {
            let lane_height = clip_rect.height() * 0.5;
            egui::Rect::from_min_max(
                egui::pos2(
                    clip_rect.left(),
                    clip_rect.top() + display_channel as f32 * lane_height,
                ),
                egui::pos2(
                    clip_rect.right(),
                    clip_rect.top() + (display_channel + 1) as f32 * lane_height,
                ),
            )
        } else {
            clip_rect
        };
        let amplitude = (lane.height() * 0.42).max(1.0);
        let center_y = lane.center().y;
        let color = if stereo && display_channel == 1 {
            Color32::from_rgba_unmultiplied(222, 212, 255, 155)
        } else {
            Color32::from_rgba_unmultiplied(201, 220, 255, 155)
        };
        for column in 0..columns {
            let frame_start = u128::from(source_start)
                + u128::from(source_end - source_start) * column as u128 / columns as u128;
            let frame_end = u128::from(source_start)
                + u128::from(source_end - source_start) * (column + 1) as u128 / columns as u128;
            let first_peak = (frame_start * peak_count / frame_count) as usize;
            let last_peak = ((frame_end * peak_count / frame_count) as usize)
                .max(first_peak + 1)
                .min(peaks.len());
            let mut minimum = f32::INFINITY;
            let mut maximum = f32::NEG_INFINITY;
            for peak in &peaks[first_peak.min(peaks.len() - 1)..last_peak] {
                minimum = minimum.min(peak.minimum);
                maximum = maximum.max(peak.maximum);
            }
            if !minimum.is_finite() || !maximum.is_finite() {
                continue;
            }
            let x = clip_rect.left() + (column as f32 + 0.5) * clip_rect.width() / columns as f32;
            painter.line_segment(
                [
                    egui::pos2(x, center_y - maximum * amplitude),
                    egui::pos2(x, center_y - minimum * amplitude),
                ],
                Stroke::new(1.0, color),
            );
        }
    }
}

fn draw_spectral_audio_clip(
    painter: &egui::Painter,
    clip_rect: egui::Rect,
    waveform: &AudioWaveform,
    source_start: u64,
    source_end: u64,
) {
    if waveform.spectral_bands.is_empty() || source_start >= source_end {
        return;
    }
    let column_count = waveform.spectral_bands.len();
    let Some(first_bands) = waveform.spectral_bands.first() else {
        return;
    };
    let band_count = first_bands.len();
    if band_count == 0 {
        return;
    }
    let total_frames = u128::from(waveform.frame_count);
    let first_column = (u128::from(source_start) * column_count as u128 / total_frames) as usize;
    let last_column = ((u128::from(source_end) * column_count as u128).div_ceil(total_frames)
        as usize)
        .clamp(first_column + 1, column_count);
    let visible_columns = last_column.saturating_sub(first_column).max(1);
    let source_span = u128::from(source_end - source_start);
    let band_height = clip_rect.height() / band_count as f32;

    for column_index in first_column.min(column_count - 1)..last_column {
        let center_frame = ((column_index as f64 + 0.5) * waveform.frame_count as f64
            / column_count as f64) as u64;
        let position = u128::from(
            center_frame
                .saturating_sub(source_start)
                .min(source_end - 1),
        );
        let x = clip_rect.left() + position as f32 * clip_rect.width() / source_span as f32;
        let width = (clip_rect.width() / visible_columns as f32).max(1.0);
        let left = (x - width * 0.5).max(clip_rect.left());
        let right = (x + width * 0.5).min(clip_rect.right());
        if right <= left {
            continue;
        }
        for band in 0..band_count {
            let intensity = f32::from(waveform.spectral_bands[column_index][band]) / 255.0;
            if intensity < 0.02 {
                continue;
            }
            let color = if intensity < 0.62 {
                blend_color(PANEL_DARK, PURPLE, intensity / 0.62)
            } else {
                blend_color(PURPLE, BLUE, (intensity - 0.62) / 0.38)
            };
            let top = clip_rect.bottom() - (band + 1) as f32 * band_height;
            let cell = egui::Rect::from_min_max(
                egui::pos2(left, top),
                egui::pos2(right, top + band_height + 0.5),
            );
            painter.rect_filled(cell, egui::CornerRadius::ZERO, color);
        }
    }
}

fn blend_color(start: Color32, end: Color32, amount: f32) -> Color32 {
    let amount = amount.clamp(0.0, 1.0);
    let blend = |first: u8, second: u8| {
        (f32::from(first) + (f32::from(second) - f32::from(first)) * amount).round() as u8
    };
    Color32::from_rgb(
        blend(start.r(), end.r()),
        blend(start.g(), end.g()),
        blend(start.b(), end.b()),
    )
}

fn snap_note_tick(value: i64, quantum: u32, minimum: u32) -> u32 {
    let quantum = u64::from(quantum.max(1));
    let value = value.max(0) as u64;
    let snapped = value
        .saturating_add(quantum / 2)
        .checked_div(quantum)
        .unwrap_or(0)
        .saturating_mul(quantum)
        .clamp(u64::from(minimum), u64::from(u32::MAX));
    snapped as u32
}

fn piano_roll_controller_value_range(
    controllers: &[PatternController],
    stream: Option<(u8, u8)>,
) -> (f64, f64) {
    let mut minimum = f64::INFINITY;
    let mut maximum = f64::NEG_INFINITY;
    for controller in controllers.iter().filter(|controller| {
        stream.is_none_or(|(channel, flags)| {
            controller.channel == channel && controller.flags == flags
        })
    }) {
        let value = f64::from(controller.value());
        if value.is_finite() {
            minimum = minimum.min(value);
            maximum = maximum.max(value);
        }
    }

    if !minimum.is_finite() || !maximum.is_finite() {
        return (0.0, 1.0);
    }
    if minimum >= 0.0 && maximum <= 1.0 {
        return (0.0, 1.0);
    }

    let padding = (maximum - minimum).max(1.0) * 0.08;
    (
        (minimum - padding).max(-f64::from(f32::MAX)),
        (maximum + padding).min(f64::from(f32::MAX)),
    )
}

fn piano_roll_controller_value_at(normalized: f32, minimum: f64, maximum: f64) -> f32 {
    let normalized = f64::from(normalized.clamp(0.0, 1.0));
    let value = minimum + normalized * (maximum - minimum);
    value.clamp(-f64::from(f32::MAX), f64::from(f32::MAX)) as f32
}

fn snap_signed_tick_delta(value: i64, quantum: u32) -> i64 {
    let quantum = u64::from(quantum.max(1));
    let magnitude = value.unsigned_abs();
    let snapped = magnitude
        .saturating_add(quantum / 2)
        .checked_div(quantum)
        .unwrap_or(0)
        .saturating_mul(quantum)
        .min(i64::MAX as u64) as i64;
    if value < 0 { -snapped } else { snapped }
}

fn playlist_audio_clip_joinable(
    left: &PlaylistClip,
    right: &PlaylistClip,
    channel_kinds: &BTreeMap<u16, Option<u8>>,
) -> bool {
    let (
        PlaylistClipTarget::Channel {
            id: left_channel_id,
        },
        PlaylistClipTarget::Channel {
            id: right_channel_id,
        },
    ) = (left.target(), right.target())
    else {
        return false;
    };
    if left_channel_id != right_channel_id
        || channel_kinds.get(&left_channel_id).copied().flatten() != Some(4)
        || left.raw_track_index != right.raw_track_index
        || left.record_size != right.record_size
        || left.pattern_base != right.pattern_base
        || left.item_index != right.item_index
        || left.track_index != right.track_index
        || left.group != right.group
        || left.unknown_word != right.unknown_word
        || left.item_flags != right.item_flags
        || left.header_bytes != right.header_bytes
        || left.clip_id != right.clip_id
        || left.reserved != right.reserved
        || left.scale != right.scale
        || left.trailing_bytes != right.trailing_bytes
        || left.length_ticks == 0
        || right.length_ticks == 0
    {
        return false;
    }
    if left
        .scale
        .is_some_and(|scale| !scale.is_finite() || (scale - 1.0).abs() > 1e-9)
    {
        return false;
    }
    let Some(left_end_ticks) = left.position_ticks.checked_add(left.length_ticks) else {
        return false;
    };
    if left_end_ticks != right.position_ticks
        || right
            .position_ticks
            .checked_add(right.length_ticks)
            .is_none()
        || !left.start_offset.is_finite()
        || !left.end_offset.is_finite()
        || !right.start_offset.is_finite()
        || !right.end_offset.is_finite()
        || left.start_offset < 0.0
        || right.start_offset < 0.0
        || left.end_offset <= left.start_offset
        || right.end_offset <= right.start_offset
        || left.end_offset.to_bits() != right.start_offset.to_bits()
    {
        return false;
    }
    true
}

fn playlist_audio_clip_join_candidates(
    clips: &[PlaylistClip],
    clip_index: usize,
    channel_kinds: &BTreeMap<u16, Option<u8>>,
    tempo_channel_ids: &BTreeSet<u16>,
) -> (Option<usize>, Option<usize>) {
    let Some(clip) = clips.get(clip_index) else {
        return (None, None);
    };
    let mut previous = clips
        .iter()
        .enumerate()
        .filter(|(candidate_index, candidate)| {
            *candidate_index != clip_index
                && playlist_audio_clip_joinable(candidate, clip, channel_kinds)
                && !playlist_tempo_overlaps_range(
                    clips,
                    tempo_channel_ids,
                    candidate.position_ticks,
                    clip.position_ticks.saturating_add(clip.length_ticks),
                )
        })
        .map(|(candidate_index, _)| candidate_index);
    let previous_clip_index = previous.next();
    let previous_clip_index = if previous.next().is_none() {
        previous_clip_index
    } else {
        None
    };

    let mut next = clips
        .iter()
        .enumerate()
        .filter(|(candidate_index, candidate)| {
            *candidate_index != clip_index
                && playlist_audio_clip_joinable(clip, candidate, channel_kinds)
                && !playlist_tempo_overlaps_range(
                    clips,
                    tempo_channel_ids,
                    clip.position_ticks,
                    candidate
                        .position_ticks
                        .saturating_add(candidate.length_ticks),
                )
        })
        .map(|(candidate_index, _)| candidate_index);
    let next_clip_index = next.next();
    let next_clip_index = if next.next().is_none() {
        next_clip_index
    } else {
        None
    };

    (previous_clip_index, next_clip_index)
}

fn playlist_pattern_clip_joinable(
    left: &PlaylistClip,
    right: &PlaylistClip,
    patterns: &[Pattern],
) -> bool {
    let (
        flp_rebuild::PlaylistClipTarget::Pattern {
            id: left_pattern_id,
        },
        flp_rebuild::PlaylistClipTarget::Pattern {
            id: right_pattern_id,
        },
    ) = (left.target(), right.target())
    else {
        return false;
    };
    if left_pattern_id != right_pattern_id
        || left.raw_track_index != right.raw_track_index
        || left.record_size != right.record_size
        || left.pattern_base != right.pattern_base
        || left.item_index != right.item_index
        || left.track_index != right.track_index
        || left.group != right.group
        || left.unknown_word != right.unknown_word
        || left.item_flags != right.item_flags
        || left.header_bytes != right.header_bytes
        || left.start_offset.to_bits() != right.start_offset.to_bits()
        || left.end_offset.to_bits() != right.end_offset.to_bits()
        || left.clip_id != right.clip_id
        || left.reserved != right.reserved
        || left.scale.map(f64::to_bits) != right.scale.map(f64::to_bits)
        || left.trailing_bytes != right.trailing_bytes
        || left.length_ticks == 0
        || right.length_ticks == 0
    {
        return false;
    }
    if left
        .scale
        .is_some_and(|scale| !scale.is_finite() || (scale - 1.0).abs() > 1e-9)
    {
        return false;
    }
    let Some(left_end_ticks) = left.position_ticks.checked_add(left.length_ticks) else {
        return false;
    };
    if left_end_ticks != right.position_ticks
        || right
            .position_ticks
            .checked_add(right.length_ticks)
            .is_none()
    {
        return false;
    }

    let Some(pattern) = patterns
        .iter()
        .find(|pattern| pattern.id == left_pattern_id)
    else {
        return false;
    };
    let inferred_length = pattern
        .notes
        .iter()
        .filter(|note| note.length > 0)
        .map(|note| u64::from(note.position) + u64::from(note.length))
        .max()
        .unwrap_or(0);
    let Some(repeat_length) = pattern
        .length_ticks
        .map(u64::from)
        .filter(|length| *length > 0)
        .or_else(|| (inferred_length > 0).then_some(inferred_length))
    else {
        return false;
    };
    u64::from(left.length_ticks).is_multiple_of(repeat_length)
        && !pattern.notes.iter().any(|note| {
            u64::from(note.position) >= repeat_length
                || (note.length > 0
                    && u64::from(note.position) % repeat_length + u64::from(note.length)
                        > repeat_length)
        })
}

fn playlist_pattern_clip_join_candidates(
    clips: &[PlaylistClip],
    clip_index: usize,
    patterns: &[Pattern],
    tempo_channel_ids: &BTreeSet<u16>,
) -> (Option<usize>, Option<usize>) {
    let Some(clip) = clips.get(clip_index) else {
        return (None, None);
    };
    let mut previous = clips
        .iter()
        .enumerate()
        .filter(|(candidate_index, candidate)| {
            *candidate_index != clip_index
                && playlist_pattern_clip_joinable(candidate, clip, patterns)
                && !playlist_tempo_overlaps_range(
                    clips,
                    tempo_channel_ids,
                    candidate.position_ticks,
                    clip.position_ticks.saturating_add(clip.length_ticks),
                )
        })
        .map(|(candidate_index, _)| candidate_index);
    let previous_clip_index = previous.next();
    let previous_clip_index = if previous.next().is_none() {
        previous_clip_index
    } else {
        None
    };

    let mut next = clips
        .iter()
        .enumerate()
        .filter(|(candidate_index, candidate)| {
            *candidate_index != clip_index
                && playlist_pattern_clip_joinable(clip, candidate, patterns)
                && !playlist_tempo_overlaps_range(
                    clips,
                    tempo_channel_ids,
                    clip.position_ticks,
                    candidate
                        .position_ticks
                        .saturating_add(candidate.length_ticks),
                )
        })
        .map(|(candidate_index, _)| candidate_index);
    let next_clip_index = next.next();
    let next_clip_index = if next.next().is_none() {
        next_clip_index
    } else {
        None
    };

    (previous_clip_index, next_clip_index)
}

fn playlist_tempo_overlaps_range(
    clips: &[PlaylistClip],
    tempo_channel_ids: &BTreeSet<u16>,
    start_ticks: u32,
    end_ticks: u32,
) -> bool {
    clips.iter().any(|candidate| {
        let PlaylistClipTarget::Channel { id } = candidate.target() else {
            return false;
        };
        tempo_channel_ids.contains(&id)
            && candidate.position_ticks < end_ticks
            && candidate
                .position_ticks
                .saturating_add(candidate.length_ticks)
                > start_ticks
    })
}

fn playlist_clip_split_position(
    pointer: egui::Pos2,
    clip_rect: egui::Rect,
    clip_position_ticks: u32,
    clip_length_ticks: u32,
    tick_scale: f32,
    ppq: u16,
    snap: bool,
) -> Option<u32> {
    if !clip_rect.contains(pointer) || !tick_scale.is_finite() || tick_scale <= 0.0 {
        return None;
    }
    let relative_ticks = ((pointer.x - clip_rect.left()) / tick_scale).round() as i64;
    let position_ticks = i64::from(clip_position_ticks).saturating_add(relative_ticks);
    let snap_ticks = if snap {
        (u32::from(ppq.max(1)) / 4).max(1)
    } else {
        1
    };
    let position_ticks = snap_note_tick(position_ticks, snap_ticks, 0);
    let clip_end_ticks = clip_position_ticks.saturating_add(clip_length_ticks);
    (position_ticks > clip_position_ticks && position_ticks < clip_end_ticks)
        .then_some(position_ticks)
}

fn playlist_measure_boundaries(
    ppq: u16,
    initial_time_signature: Option<(u8, u8)>,
    signature_changes: &[(u32, u8, u8)],
    max_tick: u32,
) -> Vec<(u32, u64)> {
    let mut changes = signature_changes.to_vec();
    changes.sort_by_key(|(position, _, _)| *position);
    let mut signature = initial_time_signature.unwrap_or((4, 4));
    signature.0 = signature.0.max(1);
    signature.1 = signature.1.max(1);
    let mut boundaries = vec![(0, 1)];
    let mut segment_start = 0u32;
    let mut measure_number = 1u64;
    let mut change_index = 0usize;

    while changes
        .get(change_index)
        .is_some_and(|(position, _, _)| *position == 0)
    {
        let (_, numerator, denominator) = changes[change_index];
        signature = (numerator.max(1), denominator.max(1));
        change_index += 1;
    }

    while let Some((position, _, _)) = changes.get(change_index).copied() {
        if position > max_tick {
            break;
        }
        if position > segment_start {
            let bar_ticks = playlist_bar_ticks(ppq, signature);
            append_playlist_measures(
                &mut boundaries,
                &mut measure_number,
                segment_start,
                position,
                bar_ticks,
            );
            if boundaries.last().is_none_or(|(tick, _)| *tick < position) {
                measure_number = measure_number.saturating_add(1);
                boundaries.push((position, measure_number));
            }
            segment_start = position;
        }
        while changes
            .get(change_index)
            .is_some_and(|(change_position, _, _)| *change_position == position)
        {
            let (_, numerator, denominator) = changes[change_index];
            signature = (numerator.max(1), denominator.max(1));
            change_index += 1;
        }
    }

    if segment_start < max_tick {
        append_playlist_measures(
            &mut boundaries,
            &mut measure_number,
            segment_start,
            max_tick,
            playlist_bar_ticks(ppq, signature),
        );
    }
    boundaries
}

fn playlist_bar_ticks(ppq: u16, time_signature: (u8, u8)) -> u64 {
    (u64::from(ppq.max(1)) * u64::from(time_signature.0.max(1)) * 4
        / u64::from(time_signature.1.max(1)))
    .max(1)
}

fn playlist_track_group_range(track_id: u32, tracks: &[PlaylistTrack]) -> Option<(u32, u32)> {
    let mut ordered_tracks = tracks.iter().collect::<Vec<_>>();
    ordered_tracks.sort_by_key(|track| track.id);
    let mut first_index = ordered_tracks
        .iter()
        .position(|track| track.id == track_id)?;
    while first_index > 0 && ordered_tracks[first_index].grouped == Some(true) {
        first_index -= 1;
    }
    let mut last_index = first_index;
    while last_index + 1 < ordered_tracks.len()
        && ordered_tracks[last_index + 1].grouped == Some(true)
    {
        last_index += 1;
    }
    Some((
        ordered_tracks[first_index].id,
        ordered_tracks[last_index].id,
    ))
}

fn playlist_group_parent_ids(tracks: &[PlaylistTrack]) -> Vec<u32> {
    let mut ordered_tracks = tracks.iter().collect::<Vec<_>>();
    ordered_tracks.sort_by_key(|track| track.id);
    ordered_tracks
        .into_iter()
        .filter(|track| track.grouped != Some(true))
        .filter_map(|track| {
            playlist_track_group_range(track.id, tracks)
                .filter(|(first, last)| *first == track.id && first < last)
                .map(|_| track.id)
        })
        .collect()
}

fn playlist_track_is_hidden(
    track_id: u32,
    tracks: &[PlaylistTrack],
    collapsed_group_ids: &BTreeSet<u32>,
) -> bool {
    tracks
        .iter()
        .find(|track| track.id == track_id)
        .is_some_and(|track| track.grouped == Some(true))
        && playlist_track_group_range(track_id, tracks)
            .is_some_and(|(parent_id, _)| collapsed_group_ids.contains(&parent_id))
}

fn playlist_seek_tick_to_frame(tick: u32, ppq: u16, tempo_bpm: f64, sample_rate: u32) -> u64 {
    if !tempo_bpm.is_finite() || tempo_bpm <= 0.0 || sample_rate == 0 {
        return 0;
    }
    let frames =
        f64::from(tick) * 60.0 * f64::from(sample_rate) / (tempo_bpm * f64::from(ppq.max(1)));
    if frames.is_finite() && frames > 0.0 {
        frames.round() as u64
    } else {
        0
    }
}

fn audio_recording_length_ticks(
    frames: u64,
    sample_rate: u32,
    ppq: u16,
    tempo_bpm: f64,
) -> Option<u32> {
    if frames == 0 || sample_rate == 0 || !tempo_bpm.is_finite() || tempo_bpm <= 0.0 {
        return None;
    }
    let ticks = frames as f64 * tempo_bpm * f64::from(ppq.max(1)) / (f64::from(sample_rate) * 60.0);
    if !ticks.is_finite() || ticks.ceil() > f64::from(u32::MAX) {
        return None;
    }
    Some((ticks.ceil() as u32).max(1))
}

fn first_available_playlist_track(
    arrangement: &Arrangement,
    start_tick: u32,
    length_ticks: u32,
) -> Option<u16> {
    let end_tick = start_tick.checked_add(length_ticks)?;
    (0..=499).find(|track_index| {
        arrangement.clips.iter().all(|clip| {
            let clip_end = clip.position_ticks.saturating_add(clip.length_ticks);
            let overlaps = clip.position_ticks < end_tick && start_tick < clip_end;
            !overlaps
                || clip
                    .track_index
                    .is_some_and(|clip_track| clip_track != *track_index)
        })
    })
}

fn arrangement_has_audio_clip_template(document: &FlpDocument, arrangement_id: u16) -> bool {
    let audio_channel_ids = document
        .channels()
        .into_iter()
        .filter(|channel| channel.kind() == Some(4) && channel.sample_path().is_some())
        .map(|channel| channel.id())
        .collect::<BTreeSet<_>>();
    if audio_channel_ids.is_empty() {
        return false;
    }
    document
        .arrangements()
        .ok()
        .and_then(|arrangements| {
            arrangements
                .into_iter()
                .find(|arrangement| arrangement.id == arrangement_id)
        })
        .is_some_and(|arrangement| {
            arrangement.clips.iter().any(|clip| {
                matches!(clip.target(), PlaylistClipTarget::Channel { id } if audio_channel_ids.contains(&id))
            })
        })
}

fn playlist_measure_at_tick(
    ppq: u16,
    initial_time_signature: Option<(u8, u8)>,
    signature_changes: &[(u32, u8, u8)],
    tick: u32,
) -> (u32, u64) {
    let mut changes = signature_changes.to_vec();
    changes.sort_by_key(|(position, _, _)| *position);
    let mut signature = initial_time_signature.unwrap_or((4, 4));
    signature.0 = signature.0.max(1);
    signature.1 = signature.1.max(1);
    let mut segment_start = 0u32;
    let mut measure_number = 1u64;
    let mut change_index = 0usize;

    while let Some((position, _, _)) = changes.get(change_index).copied() {
        if position > tick {
            break;
        }
        if position > segment_start {
            let bar_ticks = playlist_bar_ticks(ppq, signature);
            let elapsed_ticks = u64::from(position - segment_start);
            let completed_bars = elapsed_ticks / bar_ticks;
            measure_number = measure_number.saturating_add(completed_bars);
            let last_boundary =
                u64::from(segment_start).saturating_add(completed_bars.saturating_mul(bar_ticks));
            if last_boundary < u64::from(position) {
                measure_number = measure_number.saturating_add(1);
            }
            segment_start = position;
        }
        while changes
            .get(change_index)
            .is_some_and(|(change_position, _, _)| *change_position == position)
        {
            let (_, numerator, denominator) = changes[change_index];
            signature = (numerator.max(1), denominator.max(1));
            change_index += 1;
        }
    }

    let bar_ticks = playlist_bar_ticks(ppq, signature);
    let elapsed_ticks = u64::from(tick - segment_start);
    let completed_bars = elapsed_ticks / bar_ticks;
    let bar_start = u64::from(segment_start).saturating_add(completed_bars * bar_ticks);
    (
        bar_start.min(u64::from(u32::MAX)) as u32,
        measure_number.saturating_add(completed_bars),
    )
}

fn playlist_song_position_label(
    tick: f64,
    ppq: u16,
    initial_time_signature: Option<(u8, u8)>,
    signature_changes: &[(u32, u8, u8)],
) -> String {
    let tick = if tick.is_finite() {
        tick.clamp(0.0, f64::from(u32::MAX))
    } else {
        0.0
    };
    let position_ticks = tick.floor() as u32;
    let (bar_start, bar) = playlist_measure_at_tick(
        ppq,
        initial_time_signature,
        signature_changes,
        position_ticks,
    );
    let (_, denominator) =
        playlist_signature_at_tick(initial_time_signature, signature_changes, position_ticks);
    let beat_ticks = f64::from(ppq.max(1)) * 4.0 / f64::from(denominator.max(1));
    let within_bar = tick - f64::from(bar_start);
    let beat = (within_bar / beat_ticks).floor() as u64 + 1;
    let tick_in_beat = (within_bar % beat_ticks).floor() as u64;
    format!("{bar}:{beat:02}:{tick_in_beat:03}")
}

fn playlist_signature_at_tick(
    initial_time_signature: Option<(u8, u8)>,
    signature_changes: &[(u32, u8, u8)],
    tick: u32,
) -> (u8, u8) {
    let mut signature = initial_time_signature.unwrap_or((4, 4));
    signature.0 = signature.0.max(1);
    signature.1 = signature.1.max(1);
    let mut changes = signature_changes.to_vec();
    changes.sort_by_key(|(position, _, _)| *position);
    for (position, numerator, denominator) in changes {
        if position > tick {
            break;
        }
        signature = (numerator.max(1), denominator.max(1));
    }
    signature
}

fn append_playlist_measures(
    boundaries: &mut Vec<(u32, u64)>,
    measure_number: &mut u64,
    segment_start: u32,
    segment_end: u32,
    bar_ticks: u64,
) {
    let mut tick = u64::from(segment_start).saturating_add(bar_ticks.max(1));
    while tick <= u64::from(segment_end) {
        if boundaries
            .last()
            .is_none_or(|(last_tick, _)| *last_tick < tick as u32)
        {
            *measure_number = (*measure_number).saturating_add(1);
            boundaries.push((tick as u32, *measure_number));
        }
        tick = tick.saturating_add(bar_ticks.max(1));
        if tick == u64::MAX {
            break;
        }
    }
}

fn playlist_clip_drag_edit(
    drag: ActivePlaylistClipDrag,
    pointer: egui::Pos2,
    tick_scale: f32,
    row_height: f32,
    ppq: u16,
    snap: bool,
    max_track_index: u16,
) -> PlaylistClipEdit {
    let tick_scale = tick_scale.max(f32::EPSILON);
    let tick_delta = ((pointer.x - drag.start_pointer.x) / tick_scale).round() as i64;
    let snap_ticks = if snap {
        (u32::from(ppq.max(1)) / 4).max(1)
    } else {
        1
    };

    match drag.kind {
        PlaylistClipDragKind::Move => {
            let track_delta = if row_height > 0.0 {
                ((pointer.y - drag.start_pointer.y) / row_height).round() as i32
            } else {
                0
            };
            let max_track_index = max_track_index
                .min(499)
                .max(drag.start_track_index.min(499));
            let track_index = (i32::from(drag.start_track_index) + track_delta)
                .clamp(0, i32::from(max_track_index)) as u16;
            PlaylistClipEdit {
                position_ticks: Some(snap_note_tick(
                    i64::from(drag.start_position_ticks).saturating_add(tick_delta),
                    snap_ticks,
                    0,
                )),
                raw_track_index: Some(499 - track_index),
                ..PlaylistClipEdit::default()
            }
        }
        PlaylistClipDragKind::Resize => PlaylistClipEdit {
            length_ticks: Some(snap_note_tick(
                i64::from(drag.start_length_ticks).saturating_add(tick_delta),
                snap_ticks,
                1,
            )),
            ..PlaylistClipEdit::default()
        },
        PlaylistClipDragKind::Slip => {
            let tick_delta = if snap {
                snap_signed_tick_delta(tick_delta, snap_ticks)
            } else {
                tick_delta
            };
            let tempo_bpm = drag.tempo_bpm.max(f64::MIN_POSITIVE);
            let delta_ms = tick_delta as f64 * 60_000.0 / (f64::from(ppq.max(1)) * tempo_bpm);
            let window_length_ms = (drag.start_source_end_ms - drag.start_source_start_ms).max(0.0);
            let max_start_ms = (drag.source_length_ms - window_length_ms).max(0.0);
            let start_offset =
                (drag.start_source_start_ms + delta_ms as f32).clamp(0.0, max_start_ms);
            PlaylistClipEdit {
                start_offset: Some(start_offset),
                end_offset: Some(start_offset + window_length_ms),
                ..PlaylistClipEdit::default()
            }
        }
    }
}

fn note_from_grid_position(
    pointer: egui::Pos2,
    grid: PianoRollGrid,
    channel_id: u16,
) -> Option<PatternNote> {
    let grid_left = grid.rect.left() + grid.keyboard_width;
    if !grid.rect.contains(pointer)
        || pointer.x < grid_left
        || grid.tick_scale <= 0.0
        || grid.key_height <= 0.0
    {
        return None;
    }
    let ticks_from_start = ((pointer.x - grid_left) / grid.tick_scale).round() as i64;
    let row = ((pointer.y - grid.rect.top()) / grid.key_height).floor() as u16;
    let key = grid
        .key_high
        .saturating_sub(row)
        .clamp(grid.key_low, grid.key_high);
    Some(PatternNote {
        position: snap_note_tick(ticks_from_start, grid.snap_ticks, 0),
        channel_id,
        length: u32::from(grid.ppq).max(1),
        key,
        velocity: 100,
        ..PatternNote::default()
    })
}

fn playlist_pattern_recording_offset(
    playhead_tick: f64,
    pattern_id: u16,
    clips: &[PlaylistClip],
) -> Option<u32> {
    clips
        .iter()
        .filter_map(|clip| {
            if clip.track_index.is_none()
                || clip.length_ticks == 0
                || clip
                    .scale
                    .is_some_and(|scale| !scale.is_finite() || (scale - 1.0).abs() > 1e-9)
                || !matches!(clip.target(), PlaylistClipTarget::Pattern { id } if id == pattern_id)
            {
                return None;
            }
            let local_tick = playlist_clip_local_recording_offset(
                playhead_tick,
                clip.position_ticks,
                clip.length_ticks,
            )?;
            Some((clip.position_ticks, local_tick))
        })
        .max_by_key(|(clip_start, _)| *clip_start)
        .map(|(_, local_tick)| local_tick)
}

fn playlist_clip_local_recording_offset(
    playhead_tick: f64,
    clip_position_ticks: u32,
    clip_length_ticks: u32,
) -> Option<u32> {
    if !playhead_tick.is_finite() || playhead_tick < 0.0 || clip_length_ticks == 0 {
        return None;
    }
    let clip_start = f64::from(clip_position_ticks);
    let clip_end = clip_start + f64::from(clip_length_ticks);
    if playhead_tick < clip_start || playhead_tick >= clip_end {
        return None;
    }
    let local_tick = (playhead_tick - clip_start)
        .round()
        .clamp(0.0, f64::from(clip_length_ticks.saturating_sub(1)));
    Some(local_tick as u32)
}

