    fn playlist_track_arrangement_fixture(clips: &[(u32, u32, u16)]) -> Arrangement {
        let mut event_stream = vec![0x63, 3, 0];
        let mut clip_payload = Vec::with_capacity(clips.len() * 80);
        for (position, length, raw_track_index) in clips {
            let mut record = [0u8; 80];
            record[0..4].copy_from_slice(&position.to_le_bytes());
            record[4..6].copy_from_slice(&0x5000u16.to_le_bytes());
            record[6..8].copy_from_slice(&0x5007u16.to_le_bytes());
            record[8..12].copy_from_slice(&length.to_le_bytes());
            record[12..14].copy_from_slice(&raw_track_index.to_le_bytes());
            record[20..24].copy_from_slice(&[0x40, 0x64, 0x80, 0x80]);
            record[24..28].copy_from_slice(&0.0f32.to_le_bytes());
            record[28..32].copy_from_slice(&1.0f32.to_le_bytes());
            record[64..72].copy_from_slice(&1.0f64.to_le_bytes());
            clip_payload.extend_from_slice(&record);
        }
        event_stream.push(0xE9);
        let mut encoded_length = clip_payload.len() as u32;
        while encoded_length >= 0x80 {
            event_stream.push((encoded_length as u8) | 0x80);
            encoded_length >>= 7;
        }
        event_stream.push(encoded_length as u8);
        event_stream.extend_from_slice(&clip_payload);

        let mut bytes = b"FLhd".to_vec();
        bytes.extend_from_slice(&6u32.to_le_bytes());
        bytes.extend_from_slice(&0u16.to_le_bytes());
        bytes.extend_from_slice(&0u16.to_le_bytes());
        bytes.extend_from_slice(&96u16.to_le_bytes());
        bytes.extend_from_slice(b"FLdt");
        bytes.extend_from_slice(&(event_stream.len() as u32).to_le_bytes());
        bytes.extend_from_slice(&event_stream);
        FlpDocument::parse(&bytes)
            .expect("Playlist track fixture should parse")
            .arrangements()
            .expect("Playlist fixture should have an arrangement")
            .remove(0)
    }

    fn mixer_parameter_fixture(records: &[(u8, u16, i32)]) -> FlpDocument {
        let mut payload = Vec::with_capacity(records.len() * 12);
        for (parameter_id, channel_data, value) in records {
            payload.extend_from_slice(&[0xAA, 0xBB, 0xCC, 0xDD]);
            payload.extend_from_slice(&[*parameter_id, 0]);
            payload.extend_from_slice(&channel_data.to_le_bytes());
            payload.extend_from_slice(&value.to_le_bytes());
        }
        let mut event_stream = vec![0xE1, payload.len() as u8];
        event_stream.extend_from_slice(&payload);
        let mut bytes = b"FLhd".to_vec();
        bytes.extend_from_slice(&6_u32.to_le_bytes());
        bytes.extend_from_slice(&0_u16.to_le_bytes());
        bytes.extend_from_slice(&0_u16.to_le_bytes());
        bytes.extend_from_slice(&96_u16.to_le_bytes());
        bytes.extend_from_slice(b"FLdt");
        bytes.extend_from_slice(&(event_stream.len() as u32).to_le_bytes());
        bytes.extend_from_slice(&event_stream);
        FlpDocument::parse(&bytes).expect("Mixer parameter fixture should parse")
    }

    fn piano_roll_color_fixture() -> FlpDocument {
        let mut note_records = Vec::new();
        for (channel_id, midi_channel) in [(0u16, 0xA3), (0, 0xB4), (1, 0xC5)] {
            let mut record = [0; 24];
            record[4..6].copy_from_slice(&0x4000u16.to_le_bytes());
            record[6..8].copy_from_slice(&channel_id.to_le_bytes());
            record[8..12].copy_from_slice(&192u32.to_le_bytes());
            record[12..14].copy_from_slice(&60u16.to_le_bytes());
            record[19] = midi_channel;
            record[21] = 100;
            note_records.extend_from_slice(&record);
        }
        let mut event_stream = vec![0x40, 0, 0, 0x40, 1, 0, 0x41, 7, 0, 0xD0, 72];
        event_stream.extend_from_slice(&note_records);
        let mut bytes = b"FLhd".to_vec();
        bytes.extend_from_slice(&6u32.to_le_bytes());
        bytes.extend_from_slice(&0u16.to_le_bytes());
        bytes.extend_from_slice(&0u16.to_le_bytes());
        bytes.extend_from_slice(&96u16.to_le_bytes());
        bytes.extend_from_slice(b"FLdt");
        bytes.extend_from_slice(&(event_stream.len() as u32).to_le_bytes());
        bytes.extend_from_slice(&event_stream);
        FlpDocument::parse(&bytes).expect("Piano roll color fixture should parse")
    }

    #[test]
    fn piano_roll_color_change_recolors_selection_or_target_channel_and_preserves_unknown_bits() {
        let mut document = piano_roll_color_fixture();
        let selected = BTreeSet::from([(7, 0, 0)]);
        assert_eq!(
            recolor_piano_roll_notes(&mut document, 7, 0, &selected, 2),
            Ok(1)
        );

        let notes = document.patterns().unwrap().remove(0).notes;
        assert_eq!(notes[0].midi_channel, 0xA2);
        assert_eq!(notes[1].midi_channel, 0xB4);
        assert_eq!(notes[2].midi_channel, 0xC5);

        assert_eq!(
            recolor_piano_roll_notes(&mut document, 7, 0, &BTreeSet::new(), 6),
            Ok(2)
        );
        let notes = document.patterns().unwrap().remove(0).notes;
        assert_eq!(notes[0].midi_channel, 0xA6);
        assert_eq!(notes[1].midi_channel, 0xB6);
        assert_eq!(notes[2].midi_channel, 0xC5);
    }

